USE `cy`;

/*Table structure for table `client` */

DROP TABLE IF EXISTS `client`;

CREATE TABLE `client` (
  `id` int NOT NULL AUTO_INCREMENT,
  `membership_id` int NOT NULL,
  `full_name` varchar(55) NOT NULL,
  `membership_type_id` int NOT NULL,
  `membership` varchar(55) DEFAULT NULL,
  `email` varchar(55) DEFAULT NULL,
  `phone_number` varchar(20) DEFAULT NULL,
  `gender` varchar(55) NOT NULL,
  `age` int DEFAULT NULL,
  `birthday` date DEFAULT NULL,
  `membership_start` datetime DEFAULT CURRENT_TIMESTAMP,
  `membership_end` datetime DEFAULT NULL,
  `membership_status` varchar(20) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `profile_pic` mediumblob,
  PRIMARY KEY (`id`),
  UNIQUE KEY `membership_id` (`membership_id`),
  KEY `fk_membership_type` (`membership_type_id`),
  KEY `idx_membership_id` (`membership_id`),
  CONSTRAINT `fk_membership_type` FOREIGN KEY (`membership_type_id`) REFERENCES `clientmembershiptype` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=91 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

