/*Table structure for table `clientattendance` */

DROP TABLE IF EXISTS `clientattendance`;

CREATE TABLE `clientattendance` (
  `id` int NOT NULL AUTO_INCREMENT,
  `membership_id` int NOT NULL,
  `date` date NOT NULL,
  `check_in_time` time DEFAULT NULL,
  `attendance_status` varchar(55) DEFAULT 'Absent',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_client_membership` (`membership_id`),
  CONSTRAINT `fk_client_membership` FOREIGN KEY (`membership_id`) REFERENCES `client` (`membership_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `clientattendance` */

/*Table structure for table `clientmembershiptype` */

DROP TABLE IF EXISTS `clientmembershiptype`;

CREATE TABLE `clientmembershiptype` (
  `id` int NOT NULL AUTO_INCREMENT,
  `membership_type` varchar(55) NOT NULL,
  `duration` int NOT NULL DEFAULT '30',
  `price` decimal(10,2) NOT NULL,
  `benefits` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `clientmembershiptype` */

insert  into `clientmembershiptype`(`id`,`membership_type`,`duration`,`price`,`benefits`,`created_at`) values 
