/*Table structure for table `finalrevenue` */

DROP TABLE IF EXISTS `finalrevenue`;

CREATE TABLE `finalrevenue` (
  `id` int NOT NULL AUTO_INCREMENT,
  `revenue_date` date NOT NULL,
  `original_revenue` decimal(10,2) NOT NULL,
  `liabilities` decimal(10,2) NOT NULL DEFAULT '0.00',
  `final_revenue` decimal(10,2) GENERATED ALWAYS AS ((`original_revenue` - `liabilities`)) STORED,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

