/*Table structure for table `itemrestock` */

DROP TABLE IF EXISTS `itemrestock`;

CREATE TABLE `itemrestock` (
  `id` int NOT NULL AUTO_INCREMENT,
  `item_id` int NOT NULL,
  `item_name` varchar(55) DEFAULT NULL,
  `total_cost` decimal(10,2) DEFAULT NULL,
  `restock_amount` int NOT NULL,
  `liability_cost` decimal(10,2) NOT NULL,
  `restock_date` datetime NOT NULL,
  `has_paid` bit(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `item_id` (`item_id`)
