/*Table structure for table `itemsale` */

DROP TABLE IF EXISTS `itemsale`;

CREATE TABLE `itemsale` (
  `id` int NOT NULL AUTO_INCREMENT,
  `item_id` int NOT NULL,
  `item_name` varchar(55) DEFAULT NULL,
  `item_category` varchar(55) DEFAULT NULL,
  `sale` decimal(10,2) NOT NULL,
  `quantity_sold` int NOT NULL,
  `price` decimal(10,2) DEFAULT NULL,
  `sold_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `is_recorded` bit(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_item_id` (`item_id`),
  CONSTRAINT `fk_item_id` FOREIGN KEY (`item_id`) REFERENCES `item` (`item_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `itemsale_chk_1` CHECK ((`sale` >= 0)),
  CONSTRAINT `itemsale_chk_2` CHECK ((`quantity_sold` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

